package com.projecteden.evolution.controller;import java.util.List;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import com.projecteden.evolution.dto.*;import com.projecteden.evolution.service.EvolutionService;import com.projecteden.user.domain.User;@RestController@RequestMapping("/api/evolution")public class EvolutionController{private final EvolutionService service;public EvolutionController(EvolutionService service){this.service=service;}@GetMapping("/me")public WorldEvolutionResponse evolution(@AuthenticationPrincipal User user){return service.getEvolutionByUserId(user.getId());}@GetMapping("/history")public List<EvolutionHistoryResponse> history(@AuthenticationPrincipal User user){return service.getHistoryByUserId(user.getId());}@GetMapping("/decorations")public List<WorldDecorationResponse> decorations(@AuthenticationPrincipal User user){return service.getDecorationsByUserId(user.getId());}}
